// エラー情報を解析し、重要度を判定する
const errorData = $input.item.json;
const now = new Date();

// エラーの詳細情報を抽出
const errorInfo = {
  timestamp: now.toLocaleString('ja-JP', {timeZone: 'Asia/Tokyo'}),
  workflowName: errorData.workflow?.name || 'Unknown Workflow',
  nodeName: errorData.node?.name || 'Unknown Node',
  errorMessage: errorData.error?.message || 'Unknown Error',
  errorType: errorData.error?.type || 'Unknown Type',
  errorStack: errorData.error?.stack || '',
  executionId: errorData.execution?.id || 'Unknown',
  retryable: false,
  severity: 'medium'
};

// エラーの重要度判定
const criticalKeywords = ['credential', 'auth', 'permission', 'quota', 'limit exceeded'];
const retryableKeywords = ['timeout', 'network', 'temporary', 'rate limit', 'connection'];
const errorLower = errorInfo.errorMessage.toLowerCase();

if (criticalKeywords.some(keyword => errorLower.includes(keyword))) {
  errorInfo.severity = 'critical';
} else if (retryableKeywords.some(keyword => errorLower.includes(keyword))) {
  errorInfo.retryable = true;
  errorInfo.severity = 'low';
}

// Slack用の整形されたメッセージを生成
const slackMessage = `🚨 *N8Nワークフローエラー*\n` +
  `⏰ 時刻: ${errorInfo.timestamp}\n` +
  `🔧 ワークフロー: ${errorInfo.workflowName}\n` +
  `📍 ノード: ${errorInfo.nodeName}\n` +
  `❌ エラー: ${errorInfo.errorMessage}\n` +
  `🔍 実行ID: ${errorInfo.executionId}\n` +
  `⚠️ 重要度: ${errorInfo.severity.toUpperCase()}${errorInfo.retryable ? ' (再試行可能)' : ''}`;

const emailSubject = `[${errorInfo.severity.toUpperCase()}] N8N情報収集エラー - ${errorInfo.nodeName}`;
const emailBody = `N8Nワークフローでエラーが発生しました。\n\n` +
  `時刻: ${errorInfo.timestamp}\n` +
  `ワークフロー: ${errorInfo.workflowName}\n` +
  `ノード: ${errorInfo.nodeName}\n` +
  `エラーメッセージ: ${errorInfo.errorMessage}\n` +
  `エラータイプ: ${errorInfo.errorType}\n` +
  `実行ID: ${errorInfo.executionId}\n\n` +
  `スタックトレース:\n${errorInfo.errorStack}\n\n` +
  `N8Nのログを確認して対応してください。`;

return [{ 
  json: {
    ...errorInfo,
    slackMessage,
    emailSubject,
    emailBody
  }
}];
